package com.ruoyi.framework.audit;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class WeightStageAuditTest {
 @Test void stagePathDoesNotTreatItemAndProcessIdsAsWorkOrderIds(){var j=mock(JdbcTemplate.class);var ids=new ArrayList<Long>();when(j.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{if(a.<String>getArgument(0).equals("SELECT * FROM metal_work_order WHERE work_order_id=?")){Long id=a.getArgument(1);ids.add(id);return List.of(new HashMap<>(Map.of("work_order_id",id,"factory_id",7L,"order_no","WO"+id)));}return List.of();});var c=new AuditContext();c.path="/metal/work-order/10/weight-stage/20/30/close";c.actorId=1L;var r=new AuditRecorder(j,mock(PlatformTransactionManager.class)).snapshot(c,Map.of("version",1,"reason","核对结束"),null);assertEquals(Set.of("10"),r.keySet());assertEquals(List.of(10L),ids);}
 @Test void stageUuidIsNotLookedUpAsWorkOrderCreationUuid(){var j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenReturn(List.of());var c=new AuditContext();c.path="/metal/work-order/10/weight-stage/20/30/close";c.actorId=1L;new AuditRecorder(j,mock(PlatformTransactionManager.class)).snapshot(c,Map.of("requestId",UUID.randomUUID().toString()),null);verify(j,never()).queryForList(contains("WHERE request_id"),any(Object[].class));}
 @Test void deniedForeignStageSnapshotDoesNotCaptureWorkDetails(){var j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenAnswer(a->a.<String>getArgument(0).equals("SELECT * FROM metal_work_order WHERE work_order_id=?")?List.of(new HashMap<>(Map.of("work_order_id",10L,"factory_id",7L,"order_no","WO10"))):List.of());var c=new AuditContext();c.path="/metal/work-order/10/weight-stage/20/30/close";c.actorId=2L;c.actorFactory=8L;assertTrue(new AuditRecorder(j,mock(PlatformTransactionManager.class)).snapshot(c,Map.of(),null).isEmpty());assertTrue(c.factories.isEmpty());}
}
